&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;                return&lt;/span&gt;&lt;span style=&#34;color:#AB5959;--shiki-dark:#CB7676&#34;&gt; new&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt; RegExp&lt;/span&gt;&lt;span style=&#34;color:#a13865;--shiki-dark:#d9739f&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;LOCAL&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;path&lt;/span&gt;&lt;span style=&#34;color:#AB5959;--shiki-dark:#CB7676&#34;&gt; +&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt; &#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;$&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#a13865;--shiki-dark:#d9739f&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;test&lt;/span&gt;&lt;span style=&#34;color:#a13865;--shiki-dark:#d9739f&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;uri&lt;/span&gt;&lt;span style=&#34;color:#a13865;--shiki-dark:#d9739f&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;            &lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;&amp;#123;&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;%- if theme.quicklink.ignores %&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;,&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;                &lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;&amp;#123;&lt;/span&gt;&lt;span style=&#34;color:#a13865;--shiki-dark:#d9739f&#34;&gt;&amp;#123;&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; theme&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;quicklink&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;ignores&lt;/span&gt;&lt;span style=&#34;color:#AB5959;--shiki-dark:#CB7676&#34;&gt;|&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;safedump&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &lt;/span&gt;&lt;span style=&#34;color:#a13865;--shiki-dark:#d9739f&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;            &lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;&amp;#123;&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;%- endif %&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;        &lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;    &lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&amp;#x3C;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;/&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;script&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h1 id=&#34;front-matter-控制&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#front-matter-控制&#34;&gt;#&lt;/a&gt; &lt;code&gt;Front-matter&lt;/code&gt; 控制&lt;/h1&gt;
&lt;p&gt;默认文章实效性检查是启用的，对于不想启用文章实效性的文章&lt;/p&gt;
&lt;p&gt;可以在文章头部的 &lt;code&gt;Front-matter&lt;/code&gt; 信息强制指定关闭实效性检测&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;---&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;isOutdated: false  #关闭检查文章实效性&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;---&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h1 id=&#34;效果预览&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#效果预览&#34;&gt;#&lt;/a&gt; 效果预览&lt;/h1&gt;
&lt;div class=&#34;note warning&#34;&gt;
&lt;p&gt;&lt;span class=&#34;label warning&#34;&gt;时效性提示&lt;/span&gt;&lt;br /&gt;
这是一篇发布于 x 天前，最后一次更新距今已经 y 天的文章，部分内容可能已经过时，请注意甄别。&lt;/p&gt;
&lt;/div&gt;
&lt;p&gt;或者您看到本文时，本文正文顶部已经出现了实效性提示。&lt;/p&gt;

 &lt;h1 id=&#34;引言&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#引言&#34;&gt;#&lt;/a&gt; 引言&lt;/h1&gt;
&lt;div class=&#34;note info&#34;&gt;
&lt;p&gt;&lt;code&gt;cdn.jsdelivr.net&lt;/code&gt; 知名的免费cdn服务提供商，在去年年底由于大陆域名备案的问题，国内 &lt;code&gt;cdn&lt;/code&gt; 解析异常时常无法连接到服务器&lt;/p&gt;
&lt;p&gt;尤其是重度依赖 &lt;code&gt;jsDelivr&lt;/code&gt; 的 &lt;code&gt;Shoka&lt;/code&gt; 主题，在这种情况下由于资源无法加载完成导致网页卡顿，显示效果异常等一系列问题&lt;/p&gt;
&lt;p&gt;于是决定探索资源本地化方案去除对 &lt;code&gt;jsDelivr&lt;/code&gt; 的依赖&lt;/p&gt;
&lt;/div&gt;
&lt;p&gt;&lt;s&gt;截止到目前国内的 &lt;code&gt;cdn.jsdelivr.net&lt;/code&gt; 的 &lt;code&gt;DNS&lt;/code&gt; 污染貌似已经解除了，不过资源本地化还是有很多好处的，记录下过程权当自己的备忘了。&lt;/s&gt;&lt;/p&gt;
&lt;h1 id=&#34;资源本地化&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#资源本地化&#34;&gt;#&lt;/a&gt; 资源本地化&lt;/h1&gt;
&lt;h2 id=&#34;jsdelivr依赖热点&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#jsdelivr依赖热点&#34;&gt;#&lt;/a&gt; jsDelivr依赖热点&lt;/h2&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;Shoka&lt;/code&gt; 主题用到了不少第三方组件，全部基于 &lt;code&gt;jsDelivr&lt;/code&gt; 加载，资源依赖配置在了 &lt;span class=&#34;blue&#34;&gt;主题配置文件&lt;/span&gt; &lt;code&gt;_config.shoka.yml&lt;/code&gt; 的 &lt;code&gt;vendors&lt;/code&gt; 内。&lt;/li&gt;
&lt;li&gt;依赖的组件又再次依赖 &lt;code&gt;jsDelivr&lt;/code&gt; 加载依赖
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;valine: gh/amehime/MiniValine@4.2.2-beta10/dist/MiniValine.min.js&lt;/code&gt; 再次依赖&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h2 id=&#34;依赖资源下载&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#依赖资源下载&#34;&gt;#&lt;/a&gt; 依赖资源下载&lt;/h2&gt;
&lt;p&gt;本地化的一个非常重要的部分就是，将远程资源下载到本地。&lt;span class=&#34;spoiler blur&#34; title=&#34;你知道得太多了&#34;&gt;好在依赖项不是很多哈，可以慢慢手动操作一波，就是慢点&lt;/span&gt; 🤣~~&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;label primary&#34;&gt;需要注意的是，为了最小化修改，其实应该在本地享有和链接一样的目录结构，这样可以只修改加载代码而不用修改配置&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;我们在博客主目录 &lt;code&gt;source&lt;/code&gt; 下新建 &lt;code&gt;cdn.jsdelivr.net&lt;/code&gt; 文件夹，后续下载都放在这个目录下(通过 &lt;code&gt;Hexo&lt;/code&gt; 发布后的文件地址访问将会是 &lt;code&gt;站点网址\cdn.jsdelivr.net\相对路径&lt;/code&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;vendors&lt;/code&gt; 依赖资源下载&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;很多组件基本就是加载最后压缩过的单文件 &lt;code&gt;*.min.js&lt;/code&gt;，所以直接 &lt;code&gt;py&lt;/code&gt; 脚本一波走，把 &lt;code&gt;vendors&lt;/code&gt; 内的配置全部下载到本地，同时根据链接在本地创建相对的目录结构&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-py&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;import&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; urllib&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;request&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;import&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; requests&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;import&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; re&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;import&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; os&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#AB5959;--shiki-dark:#CB7676&#34;&gt;def&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt; get_file&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;url&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;/span&gt;
