&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;            minifyURLs&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt; true&lt;/span&gt;&lt;span style=&#34;color:#A0ADA0;--shiki-dark:#758575DD&#34;&gt;                      // 压缩HTML中的链接&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;        &lt;/span&gt;&lt;span style=&#34;color:#bda437;--shiki-dark:#e6cc77&#34;&gt;}&lt;/span&gt;&lt;span style=&#34;color:#a13865;--shiki-dark:#d9739f&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;        .&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;pipe&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;gulp&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;dest&lt;/span&gt;&lt;span style=&#34;color:#a13865;--shiki-dark:#d9739f&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#39;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;./public&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#39;&lt;/span&gt;&lt;span style=&#34;color:#a13865;--shiki-dark:#d9739f&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;}&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#A0ADA0;--shiki-dark:#758575DD&#34;&gt;// 默认任务，不带任务名运行gulp时执行的任务&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;gulp&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;task&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#39;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;default&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#39;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;,&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; gulp&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;parallel&lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;(&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;    &#39;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;minify-css&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#39;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;,&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt; &#39;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;minify-js&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#39;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;,&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt; &#39;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;minify-images&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#39;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;,&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt; &#39;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;minify-html&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#39;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;,&lt;/span&gt;&lt;span style=&#34;color:#AB5959;--shiki-dark:#CB7676&#34;&gt; function&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;{&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;    console&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;log&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;----------gulp Finished----------&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;}&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h1 id=&#34;结语&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#结语&#34;&gt;#&lt;/a&gt; 结语&lt;/h1&gt;
&lt;div class=&#34;note success&#34;&gt;
&lt;p&gt;最后在 &lt;code&gt;hexo&lt;/code&gt; 三连额外插入 &lt;code&gt;gulp&lt;/code&gt; 命令即可，我愿称之为 &lt;span class=&#34;blue&#34;&gt;新推送四连&lt;/span&gt;  &lt;code&gt;hexo clean &amp;amp;&amp;amp; hexo generate &amp;amp;&amp;amp; gulp &amp;amp;&amp;amp; hexo deploy&lt;/code&gt;&lt;/p&gt;
&lt;/div&gt;

 &lt;h1 id=&#34;引言&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#引言&#34;&gt;#&lt;/a&gt; 引言&lt;/h1&gt;
&lt;div class=&#34;note info&#34;&gt;
&lt;p&gt;终于又重启博客了，平时开发折腾过程中遇到的一些问题，感觉不错的会发布到博客中。&lt;/p&gt;
&lt;p&gt;但是有些文章如果存在隐私内容，或者不打算公开的话，就不能放在博客中了，但是一些文章挂在网页上又可以方便自己查看，于是折腾了下 &lt;code&gt;Hexo&lt;/code&gt; 的文章加密&lt;/p&gt;
&lt;/div&gt;
&lt;h1 id=&#34;调研&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#调研&#34;&gt;#&lt;/a&gt; 调研&lt;/h1&gt;
&lt;p&gt;以前用 &lt;code&gt;wordpress&lt;/code&gt; 的时候，也折腾过类似的需求，由于是 &lt;span class=&#34;blue&#34;&gt;动态网站&lt;/span&gt;，所以其实还是比较方便的，这一次使用了&lt;br /&gt;
&lt;code&gt;Hexo&lt;/code&gt; 这个 &lt;span class=&#34;blue&#34;&gt;静态博客&lt;/span&gt; 框架，说实话我都怀疑有没有可行的方案🤣🤣🤣&lt;/p&gt;
&lt;p&gt;不过好在还是找到了一个 &lt;code&gt;Hexo&lt;/code&gt; 插件 &lt;code&gt;hexo-blog-encrypt&lt;/code&gt; 能够实现文章加密的需求&lt;/p&gt;
&lt;h1 id=&#34;插件安装&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#插件安装&#34;&gt;#&lt;/a&gt; 插件安装&lt;/h1&gt;
&lt;p&gt;使用如下命令安装&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;npm&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; install&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; hexo-blog-encrypt&lt;/span&gt;&lt;span style=&#34;color:#A65E2B;--shiki-dark:#C99076&#34;&gt; --save&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;该插件的使用也很方便，使用时只需要在文章的 &lt;code&gt;Front-matter&lt;/code&gt; 添加 &lt;code&gt;password&lt;/code&gt; 即可。&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-md&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;---&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;title&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; Hello World&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;date&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#A65E2B;--shiki-dark:#C99076&#34;&gt; 2022-05-13 21:18:02&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;password&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#2F798A;--shiki-dark:#4C9A91&#34;&gt; 12345&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;---&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;下面展开讲一些比较实用的设置，更详细的可以查看官方文档。 &lt;a href=&#34;https://github.com/D0n9X1n/hexo-blog-encrypt/blob/master/ReadMe.zh.md&#34;&gt;D0n9X1n/hexo-blog-encrypt: Yet, just another hexo plugin for security.&lt;/a&gt;&lt;/p&gt;
&lt;h2 id=&#34;全局加密配置&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#全局加密配置&#34;&gt;#&lt;/a&gt; 全局加密配置&lt;/h2&gt;
&lt;p&gt;分别为每篇文章设置密码，虽然很灵活，但是配置或者修改起来非常麻烦。&lt;/p&gt;
&lt;p&gt;好在，我们可以针对 &lt;code&gt;tag&lt;/code&gt; 做全局统一配置，这样需要进行加密的文章，只需要引入指定的 &lt;code&gt;tag&lt;/code&gt; 分类即可&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;Hexo&lt;/code&gt; 主配置文件 &lt;code&gt;_config.yml&lt;/code&gt; 中新增全局配置&lt;/li&gt;
&lt;/ol&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-yaml&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#A0ADA0;--shiki-dark:#758575DD&#34;&gt;# Security - hexo-blog-encrypt&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;encrypt&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;  silent&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt; true&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;  theme&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; xray&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;  abstract&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; 这是一篇加密文章，需要密码才能继续阅读。&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;  message&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; 当前文章暂不对外可见，请输入密码后查看！&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;  tags&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;    -&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;&amp;#123;&lt;/span&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;name&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; private&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;,&lt;/span&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt; password&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; hello&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;  wrong_pass_message&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; 抱歉，您输入的密码错误，请检查后重新输入。&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;其中的 &lt;code&gt;tag&lt;/code&gt; 部分可以定义多个，不同加密系列，采取不同的密码&lt;/p&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;文章头部 &lt;code&gt;Front-matter&lt;/code&gt; 引入加密的 &lt;code&gt;tag&lt;/code&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-md&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;---&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;title&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; Password Test&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;date&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#A65E2B;--shiki-dark:#C99076&#34;&gt; 2022-05-03 21:28:03&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;tags&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;    -&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; private&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;---&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这样文章就被加密了，密码就是 &lt;code&gt;private&lt;/code&gt; 标签对应的密码&lt;/p&gt;
&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;全局加密豁免&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;可能有这样的情况，属于 &lt;code&gt;private&lt;/code&gt; 标签下的某篇文章可能需要公开，不可能说把密码直接在描述信息中公开吧。&lt;/p&gt;
&lt;p&gt;好在插件配置 &lt;span class=&#34;blue&#34;&gt;优先级&lt;/span&gt; 为 &lt;code&gt;文章Front-matter&lt;/code&gt; &amp;gt; &lt;code&gt;_config.yml配置&lt;/code&gt; &amp;gt; &lt;code&gt;默认配置&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;这时候，可以在 &lt;code&gt;Front-matter&lt;/code&gt; 中对加密设置进行覆盖，只需要在使用 &lt;code&gt;加密tag&lt;/code&gt; 的前提下，结合 &lt;code&gt;password&lt;/code&gt; 来实现即可。在博客文章的头部添加 &lt;code&gt;password&lt;/code&gt; 并设置为 &lt;code&gt;&amp;quot;&amp;quot;&lt;/code&gt; 就能取消当前文章的加密&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-md&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;---&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;title&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; Password Test&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;date&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#A65E2B;--shiki-dark:#C99076&#34;&gt; 2022-05-03 21:28:03&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;tags&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;    -&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; private&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;password&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt; &#34;&#34;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;---&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;ol start=&#34;4&#34;&gt;
&lt;li&gt;全局加密设置非全局密码&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;可能有如下场景，属于 &lt;code&gt;private&lt;/code&gt; 标签下的某篇文章想要设置成不一样的密码。&lt;/p&gt;
&lt;p&gt;还是利用配置的优先级在 &lt;code&gt;Front-matter&lt;/code&gt; 中对加密设置进行覆盖即可，在博客文章的头部添加 &lt;code&gt;password&lt;/code&gt; 并设置为 &lt;span class=&#34;blue&#34;&gt;自定义密码&lt;/span&gt; 就可以使用 &lt;span class=&#34;blue&#34;&gt;自定义密码&lt;/span&gt; 加密当前文章了&lt;/p&gt;
&lt;hr /&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-md&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;---&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;title&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; Password Test&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;date&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#A65E2B;--shiki-dark:#C99076&#34;&gt; 2022-05-03 21:28:03&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;tags&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;    -&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; private&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;password&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt; &#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;special&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;---&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h1 id=&#34;shoka主题适配&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#shoka主题适配&#34;&gt;#&lt;/a&gt; Shoka主题适配&lt;/h1&gt;
&lt;h2 id=&#34;解密后目录不显示&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#解密后目录不显示&#34;&gt;#&lt;/a&gt; 解密后目录不显示&lt;/h2&gt;
&lt;p&gt;为文章设置了 &lt;span class=&#34;blue&#34;&gt;加密&lt;/span&gt; 后查看 之后，不经意间发现这些文章的目录在解密后却不显示了。&lt;/p&gt;
&lt;p&gt;在插件的 &lt;code&gt;github issues&lt;/code&gt; 中有相关问题的讨论 &lt;a href=&#34;https://github.com/D0n9X1n/hexo-blog-encrypt/issues/16&#34;&gt;解密后目录不会更新 · Issue #16&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;主要原因就是加密的时候，&lt;code&gt;post.content&lt;/code&gt; 会变成加密后的串，所以原来的 &lt;code&gt;TOC&lt;/code&gt; 生成逻辑就会针对加密后的内容。&lt;br /&gt;
所以这边我只能把原来的内容存进 &lt;code&gt;post.origin&lt;/code&gt; 字段。&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;label info&#34;&gt;&lt;font color=&#34;pink&#34;&gt;Shoka&lt;/font&gt; 主题的针对修改如下：&lt;/span&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;主题文件 &lt;code&gt;themes/shoka/layout/_macro/sidebar.njk&lt;/code&gt; 找到 &lt;span class=&#34;blue&#34;&gt;宏&lt;/span&gt; &lt;code&gt;render&lt;/code&gt;，修改目录生成部分如下&lt;/li&gt;
&lt;/ol&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-html&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&amp;#x3C;&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; class&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;inner&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#A0ADA0;--shiki-dark:#758575DD&#34;&gt;     &amp;#x3C;!--comment￼0--&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;    &amp;#123;%- if display_toc %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        &amp;#123;%- if (page.encrypt) %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;            &amp;#123;%- set toc = toc(page.origin) %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        &amp;#123;%- else %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;            &amp;#123;%- set toc = toc(page.content) %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        &amp;#123;%- endif %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        &amp;#123;%- set display_toc = toc.length &gt; 1 and display_toc %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        &amp;#123;%- set related = _category_posts(page) %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;    &amp;#123;%- endif %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#A0ADA0;--shiki-dark:#758575DD&#34;&gt;     &amp;#x3C;!--comment￼1--&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#A0ADA0;--shiki-dark:#758575DD&#34;&gt;    &amp;#x3C;!--comment￼2--&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&amp;#x3C;/&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;还是主题文件 &lt;code&gt;themes/shoka/layout/_macro/sidebar.njk&lt;/code&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;替换 &lt;code&gt;&amp;lt;div class=&amp;quot;panels&amp;quot;&amp;gt;...&amp;lt;/div&amp;gt;&lt;/code&gt; 如下&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-html&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&amp;#x3C;&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; class&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;panels&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;    &amp;#x3C;&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; class&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;inner&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;        &amp;#x3C;&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; class&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;contents panel pjax&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; data-title&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;&amp;#123;&amp;#123; __(&#39;sidebar.toc&#39;) &amp;#125;&amp;#125;&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;            &amp;#123;%- if (page.encrypt) %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;                &amp;#x3C;&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; id&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;toc-div&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; style&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;display:none&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;                    &amp;#123;%- if display_toc %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;                        &amp;#123;&amp;#123; toc &amp;#125;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;                    &amp;#123;%- endif %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;                &amp;#x3C;/&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;            &amp;#123;%- else %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;                &amp;#123;%- if display_toc %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;                    &amp;#123;&amp;#123; toc &amp;#125;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;                &amp;#123;%- endif %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;            &amp;#123;%- endif %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;        &amp;#x3C;/&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;        &amp;#x3C;&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; class&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;related panel pjax&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; data-title&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;&amp;#123;&amp;#123; __(&#39;sidebar.related&#39;) &amp;#125;&amp;#125;&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;            &amp;#123;%- if related %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;                &amp;#x3C;&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;ul&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;                    &amp;#123;&amp;#123; related &amp;#125;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;                &amp;#x3C;/&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;ul&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;            &amp;#123;%- endif %&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;        &amp;#x3C;/&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;        &amp;#x3C;&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; class&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;overview panel&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt; data-title&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;=&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt;&amp;#123;&amp;#123; __(&#39;sidebar.overview&#39;) &amp;#125;&amp;#125;&lt;/span&gt;&lt;span style=&#34;color:#B5695977;--shiki-dark:#C98A7D77&#34;&gt;&#34;&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;            &amp;#123;&amp;#123; partial(&#39;_partials/sidebar/overview.njk&#39;, &amp;#123;&amp;#125;, &amp;#123;cache: true&amp;#125;) &amp;#125;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;        &amp;#x3C;/&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;    &amp;#x3C;/&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&amp;#x3C;/&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;div&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;主要缘由是现在加密后的文章未解密之前也可以看到 &lt;span class=&#34;blue&#34;&gt;文章目录&lt;/span&gt;，虽然该目录不可点击，但是这很不 &lt;span class=&#34;blue&#34;&gt;优雅&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;理想中的效果应该是:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;当文章加密后，访客只能看到侧边栏中的 &lt;code&gt;站点概览&lt;/code&gt; 部分，不需要看到 &lt;code&gt;文章目录&lt;/code&gt; 部分。&lt;/li&gt;
&lt;li&gt;当文章解密后，访客则可以看到 &lt;code&gt;站点概览&lt;/code&gt; 和 &lt;code&gt;文章目录&lt;/code&gt; 两部分。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;查看了 &lt;code&gt;hexo-blog-encrypt&lt;/code&gt; 相关的 &lt;code&gt;issues&lt;/code&gt; &lt;a href=&#34;https://github.com/D0n9X1n/hexo-blog-encrypt/issues/67&#34;&gt;Archer主题解密后TOC依旧不显示（已按手册修改）· Issue #67&lt;/a&gt;, 最总找到了一种 &lt;span class=&#34;blue&#34;&gt;折中&lt;/span&gt; 的解决方法&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;label info&#34;&gt;这种方法并不是完全的加密，而是采用 &lt;font color=&#34;pink&#34;&gt;障眼法&lt;/font&gt; 的方式，通过查看 &lt;font color=&#34;pink&#34;&gt;html&lt;/font&gt; 源文件还是可以看到目录内容的，只是不显示罢了。&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;对于这个问题，&lt;code&gt;hexo-blog-encrypt&lt;/code&gt; 插件的作者也作了说明: &lt;a href=&#34;https://github.com/D0n9X1n/hexo-blog-encrypt/issues/162&#34;&gt;next 主题内没有 article.ejs 文件【TOC 相关】 · Issue #162 · D0n9X1n/hexo-blog-encrypt&lt;/a&gt;，暂时只能妥协。&lt;/p&gt;
&lt;p&gt;前后效果对比如下，解锁前隐藏目录，解锁后再显示目录，但是目录区域一直存在&lt;/p&gt;
&lt;p class=&#34;gallery&#34;&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/posts/39295/hexo-encrypt-toc-error.png&#34; alt=&#34;hexo-encrypt-toc-error&#34; /&gt;&lt;br /&gt;
&lt;img loading=&#34;lazy&#34; src=&#34;/posts/39295/hexo-encrypt-toc.png&#34; alt=&#34;hexo-encrypt-toc&#34; /&gt;&lt;/p&gt;
&lt;h2 id=&#34;文章元数据显示加密图标&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#文章元数据显示加密图标&#34;&gt;#&lt;/a&gt; 文章元数据显示加密图标&lt;/h2&gt;
&lt;ol&gt;
&lt;li&gt;主题语言包 &lt;code&gt;themes/shoka/languages/zh-CN.yml&lt;/code&gt; 下 &lt;code&gt;post&lt;/code&gt; 新增加密显示文字&lt;/li&gt;
&lt;/ol&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-yaml&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;post&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;    encrypt&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; 『加密』&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;下一步骤引用的 &lt;code&gt;post.encrypt&lt;/code&gt; 就是这里的配置&lt;/p&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;主题文件 &lt;code&gt;themes/shoka/layout/_macro/postmeta.njk&lt;/code&gt;, 找到 &lt;span class=&#34;blue&#34;&gt;宏&lt;/span&gt; &lt;code&gt;render&lt;/code&gt; 在  {&lt;code&gt;%- set create_title = __(&#39;post.created&#39;) + __(&#39;symbol.colon&#39;) + full_date(item.date) &lt;/code&gt;}  上修改代码如下&lt;/li&gt;
&lt;/ol&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-html&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#A0ADA0;--shiki-dark:#758575DD&#34;&gt;&amp;#x3C;!--swig￼3--&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;主题样式 &lt;code&gt;themes/shoka/source/css/_common/components/post/post.styl&lt;/code&gt; 新增样式&lt;/li&gt;
&lt;/ol&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-stylus&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;span&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;encrypt&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;    white-space&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#A65E2B;--shiki-dark:#C99076&#34;&gt; pre&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;    the-transition&lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;    font&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;        color&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; #&lt;/span&gt;&lt;span style=&#34;color:#A65E2B;--shiki-dark:#C99076&#34;&gt;d96e80&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;    &lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;    span&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;        white-space&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#A65E2B;--shiki-dark:#C99076&#34;&gt; normal&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;    &lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;    a&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;        color&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt; var&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;--primary-color&lt;/span&gt;&lt;span style=&#34;color:#a65e2b;--shiki-dark:#d4976c&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;    &lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#998418;--shiki-dark:#B8A965&#34;&gt;    margin-left&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;:&lt;/span&gt;&lt;span style=&#34;color:#2F798A;--shiki-dark:#4C9A91&#34;&gt; -0.415&lt;/span&gt;&lt;span style=&#34;color:#AB5959;--shiki-dark:#CB7676&#34;&gt;rem&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;最终效果如下，同样的效果在首页文章的预览标签也会出现~&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/posts/39295/hexo-encrypt-postmeta.png&#34; alt=&#34;hexo-encrypt-postmeta&#34; width=&#34;100%&#34; /&gt;&lt;/p&gt;
&lt;h1 id=&#34;结语&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#结语&#34;&gt;#&lt;/a&gt; 结语&lt;/h1&gt;
&lt;div class=&#34;note success&#34;&gt;
&lt;p&gt;&lt;code&gt;Hexo&lt;/code&gt; 三连完结撒花~~&lt;/p&gt;
&lt;/div&gt;

 &lt;h2 id=&#34;引言&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#引言&#34;&gt;#&lt;/a&gt; 引言&lt;/h2&gt;
&lt;p&gt;&lt;code&gt;Hexo&lt;/code&gt; 是一个快速、简洁且高效的博客框架。&lt;code&gt;Hexo&lt;/code&gt; 使用 &lt;code&gt;Markdown&lt;/code&gt;（或其他渲染引擎）解析文章，在几秒内，即可利用靓丽的主题生成静态网页。即把用户的 &lt;code&gt;markdown&lt;/code&gt; 文件，按照指定的主题解析成静态网页。&lt;/p&gt;
&lt;p&gt;简单点说 &lt;code&gt;Hexo&lt;/code&gt; 就是一个博客的框架，就好比盖房子需要的框架结构一样，这是博客搭建起来的基础，最后装修好(&lt;span class=&#34;blue&#34;&gt;各种主题&lt;/span&gt;)就完成了。&lt;/p&gt;
&lt;h2 id=&#34;优劣对比&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#优劣对比&#34;&gt;#&lt;/a&gt; 优劣对比&lt;/h2&gt;
&lt;p&gt;博客框架基本可以划分为 &lt;span class=&#34;blue&#34;&gt;静态博客&lt;/span&gt; 和 &lt;span class=&#34;blue&#34;&gt;动态博客&lt;/span&gt; 两个阵营, 这儿主要从 &lt;span class=&#34;blue&#34;&gt;静态博客&lt;/span&gt; 和 &lt;span class=&#34;blue&#34;&gt;动态博客&lt;/span&gt; 的优劣进行对比, 其他的基本属于框架本身带来的特性对比, 这个到对应官网查看描述自行比对即可&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;优势&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;Hexo&lt;/code&gt; 是一个静态博客框架, 除了其附加的易于管理，易于编辑和发布的特性之外, 还具备静态网站的所有优势&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;省心: 不用担心黑客入侵&lt;/li&gt;
&lt;li&gt;省钱: 占用空间小, 纯 &lt;code&gt;html&lt;/code&gt; 文件, 每个文件控制在几 &lt;code&gt;kb&lt;/code&gt; 以内, 10000篇内容的网站，也不过才几十 &lt;code&gt;MB&lt;/code&gt;, 随便找个免费空间丢上去就好了&lt;/li&gt;
&lt;li&gt;速度快: 页面已经存在, 而不用像动态网站那样还要临时生成, 所以打开速度快&lt;/li&gt;
&lt;li&gt;搜素引擎友好: 有利于搜索引擎收录, 有利于网站 &lt;code&gt;SEO&lt;/code&gt; 排名优化&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;strong&gt;劣势&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;blue&#34;&gt;静态博客&lt;/span&gt; 与之相对的就是 &lt;span class=&#34;blue&#34;&gt;动态博客&lt;/span&gt;, 那自然是缺少动态博客动的部分&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;缺少机动性: 常见功能评论, 其他页面动态元素(每日一句)等等, 在静态博客上都需要 &lt;code&gt;js&lt;/code&gt; 配合其他服务才能实现, 不如动态博客那样扩展简单&lt;/li&gt;
&lt;li&gt;维护成本高: 由于页面都是预生成的, 设计到框架底层或者页面增加通用元素, 所有页面需要重新生成并发布&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;当然在云服务遍地开花, 越来越成熟的框架和第三方服务面前, 静态博客的劣势基本都有妥善的解决方式, 那么其纯粹的优点这也是更多人开始使用静态博客的原因了, 当然具体的还是看个人选择。&lt;/p&gt;
&lt;h2 id=&#34;hexo构建&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#hexo构建&#34;&gt;#&lt;/a&gt; Hexo构建&lt;/h2&gt;
&lt;p&gt;一张图简单介绍下 &lt;code&gt;Hexo&lt;/code&gt; 搭建流程&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/posts/18163/mermaid/buildflow.jpeg&#34; alt=&#34;buildflow&#34; width=&#34;100%&#34; /&gt;&lt;/p&gt;
&lt;h2 id=&#34;基础环境&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基础环境&#34;&gt;#&lt;/a&gt; 基础环境&lt;/h2&gt;
&lt;h3 id=&#34;安装git&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#安装git&#34;&gt;#&lt;/a&gt; 安装Git&lt;/h3&gt;
&lt;p&gt;打开链接, 点击 &lt;span class=&#34;green&#34;&gt;绿色屏幕&lt;/span&gt; 下载对应版本安装即可&lt;/p&gt;
&lt;div class=&#34;note info&#34;&gt;
&lt;p&gt;&lt;span class=&#34;blue&#34;&gt;Git客户端下载链接&lt;/span&gt;&lt;br /&gt;
&lt;a href=&#34;https://git-scm.com/&#34;&gt;Click here, https://git-scm.com/&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;h3 id=&#34;安装nodejs&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#安装nodejs&#34;&gt;#&lt;/a&gt; 安装Node.js&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Windows: 通过安装包(下载链接, &lt;a href=&#34;https://nodejs.org/&#34;&gt;Cliek Here!&lt;/a&gt;)安装，或者通过 &lt;code&gt;nvs&lt;/code&gt; 或者 &lt;code&gt;nvm&lt;/code&gt; 安装。&lt;/li&gt;
&lt;li&gt;Mac: 使用 &lt;code&gt;Homebrew&lt;/code&gt; 或 &lt;code&gt;MacPorts&lt;/code&gt; 安装。&lt;/li&gt;
&lt;li&gt;Linux(DEB/RPM-based): 从 &lt;code&gt;NodeSource&lt;/code&gt; 安装。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;其它：使用相应的软件包管理器进行安装，可以参考由 &lt;code&gt;Node.js&lt;/code&gt; 提供的指导。&lt;/p&gt;
&lt;h2 id=&#34;安装hexo框架&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#安装hexo框架&#34;&gt;#&lt;/a&gt; 安装Hexo框架&lt;/h2&gt;
&lt;p&gt;在基础环境搭建完毕后, 即可使用 &lt;code&gt;npm&lt;/code&gt; 安装 &lt;code&gt;Hexo&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;安装过程极其简单, 一行命令即可完成, &lt;code&gt;npm&lt;/code&gt; 是安装工具, &lt;code&gt;install&lt;/code&gt;表示安装, &lt;code&gt;-g&lt;/code&gt;表示全局安装, &lt;code&gt;hexo-cli&lt;/code&gt;表示安装的是hexo框架&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;npm&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; install&lt;/span&gt;&lt;span style=&#34;color:#A65E2B;--shiki-dark:#C99076&#34;&gt; -g&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; hexo-cli&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h3 id=&#34;初始化博客目录&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#初始化博客目录&#34;&gt;#&lt;/a&gt; 初始化博客目录&lt;/h3&gt;
&lt;p&gt;新建一个存放博客的文件夹 &lt;code&gt;blogtest&lt;/code&gt; &lt;strong&gt;(可以自定义为其他名称)&lt;/strong&gt;, 并初始化&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;hexo&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; init&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; blogtest&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h3 id=&#34;安装hexo依赖&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#安装hexo依赖&#34;&gt;#&lt;/a&gt; 安装Hexo依赖&lt;/h3&gt;
&lt;p&gt;&lt;code&gt;cd&lt;/code&gt; 到 &lt;code&gt;blogtest&lt;/code&gt; 目录, 执行如下命令安装依赖环境&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;npm&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; install&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h3 id=&#34;hexo构建-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#hexo构建-2&#34;&gt;#&lt;/a&gt; Hexo构建&lt;/h3&gt;
&lt;p&gt;这儿一般称作 &lt;code&gt;Hexo&lt;/code&gt; 三连, 如下命令分别执行&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;清除博客发布目录 &lt;code&gt;public&lt;/code&gt;(部署的静态博客其实就是这个目录下的文件)&lt;/li&gt;
&lt;li&gt;重新生成发布目录&lt;/li&gt;
&lt;li&gt;本地运行 &lt;code&gt;Hexo&lt;/code&gt; 服务, 进行预览&lt;/li&gt;
&lt;/ul&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;hexo&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; clean&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &amp;#x26;&amp;#x26;&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt; hexo&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; generate&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &amp;#x26;&amp;#x26;&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt; hexo&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; server&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;此时在浏览器输入 &lt;code&gt;http://localhost:4000/&lt;/code&gt; 即可对 &lt;code&gt;hexo&lt;/code&gt; 构建的博客进行预览&lt;/p&gt;
&lt;p class=&#34;gallery&#34;&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/posts/18163/HexoBuild.png&#34; alt=&#34;HexoBuild&#34; /&gt;&lt;br /&gt;
&lt;img loading=&#34;lazy&#34; src=&#34;/posts/18163/HexoServer.png&#34; alt=&#34;HexoServer&#34; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;label info&#34;&gt;注意：有时候在浏览器输入 &lt;a href=&#34;http://locakhost:4000&#34;&gt;http://locakhost:4000&lt;/a&gt;, 没有出现网页, 可能是因为4000端口被占用了, 可以使用把上一步骤的命令 hexo server 改为 hexo server -p 5000, 指定服务使用5000端口或者其他端口就可以了。&lt;/span&gt;&lt;/p&gt;
&lt;h2 id=&#34;安装hexo主题&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#安装hexo主题&#34;&gt;#&lt;/a&gt; 安装Hexo主题&lt;/h2&gt;
&lt;p&gt;&lt;code&gt;Hexo&lt;/code&gt; 安装完成, 启动服务在网页预览时, 可以看到界面比较原始类, 这就类似毛坯房, 我们可以通过安装主题来装修这个毛坯房&lt;/p&gt;
&lt;p&gt;&lt;code&gt;Hexo&lt;/code&gt; 的主题有很多啊, 使用最多的主题就是&lt;code&gt;matery&lt;/code&gt;主题和&lt;code&gt;butterfly&lt;/code&gt;主题。这两种主题各有千秋。可以先看两种主题的风格，然后做出选择，这里以&lt;code&gt;butterfly&lt;/code&gt;主题以例。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;万能的安装方式&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;前往主题所在的 &lt;code&gt;github&lt;/code&gt; 仓库 clone 主题文件到本地博客目录的主题文件夹下面(&lt;code&gt;./blogtest/themes&lt;/code&gt;)&lt;/li&gt;
&lt;li&gt;更改博客更目录下面的配置文件 &lt;code&gt;_config.yml&lt;/code&gt;, 更改主题配置名称为目标主题名字&lt;/li&gt;
&lt;li&gt;重新 &lt;span class=&#34;blue&#34;&gt;Hexo三连&lt;/span&gt; 查看效果&lt;/li&gt;
&lt;/ol&gt;
&lt;p class=&#34;gallery&#34;&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/posts/18163/ChangeTheme.png&#34; alt=&#34;butterfly&#34; /&gt;&lt;br /&gt;
&lt;img loading=&#34;lazy&#34; src=&#34;/posts/18163/ThemeButterfly.png&#34; alt=&#34;themebutterfly&#34; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;lable warning&#34;&gt;主题的安装建议前往主题的官网, 官网一般会给出比较详细的安装指南, 很多主题需要一些额外的设置, 安装一些额外的依赖, 同时还能给出更多的定制化说明&lt;/span&gt;&lt;/p&gt;
&lt;h2 id=&#34;部署到github-pages&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#部署到github-pages&#34;&gt;#&lt;/a&gt; 部署到Github Pages&lt;/h2&gt;
&lt;p&gt;在上述操作完成后, 我们虽然能够预览博客, 但是是一个本地服务只能自己查看, 所以需要将博客进行部署部署完成后供其他人访问查看。&lt;/p&gt;
&lt;p&gt;不同于动态博客, 静态博客由于其特性, 很多服务商都有对应的托管服务(重点是免费), 比如 &lt;code&gt;Github Pages&lt;/code&gt;&lt;/p&gt;
&lt;h3 id=&#34;创建github仓库&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#创建github仓库&#34;&gt;#&lt;/a&gt; 创建Github仓库&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;在 &lt;code&gt;Github&lt;/code&gt; 新建一个仓库&lt;/li&gt;
&lt;li&gt;仓库名必须是&lt;code&gt;用户名.github.io&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;仓库名必须是&lt;code&gt;用户名.github.io&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;仓库名必须是&lt;code&gt;用户名.github.io&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;仓库必须设置为&lt;span class=&#34;blue&#34;&gt;公开&lt;/span&gt;, 因为私有的仓库是不提供免费 &lt;code&gt;Page&lt;/code&gt; 的功能的, 需要每个月额外付费。其实也不需要设置为私有, 公开就行。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;安装配置hexo-git部署插件&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#安装配置hexo-git部署插件&#34;&gt;#&lt;/a&gt; 安装配置Hexo Git部署插件&lt;/h3&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;npm&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; install&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; hexo-deployer-git&lt;/span&gt;&lt;span style=&#34;color:#A65E2B;--shiki-dark:#C99076&#34;&gt; --save&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;注意这儿 &lt;code&gt;--save&lt;/code&gt; 是保存包配置到 博客目录下 &lt;code&gt;package.json&lt;/code&gt; 文件, 当你需要多设备编辑自己的博客, 通过git管理博客配置, 在新的机器上 &lt;code&gt;check&lt;/code&gt; 直接 &lt;code&gt;npm install&lt;/code&gt;, 就不用重新配置了&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;编辑配置文件&lt;/strong&gt; &lt;code&gt;_config.yml&lt;/code&gt;, &lt;strong&gt;配置上传计划&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;拷贝上一步创建仓库的地址&lt;/li&gt;
&lt;li&gt;配置 &lt;code&gt;_config.yml&lt;/code&gt;, 新增如下配置&lt;br /&gt;
&lt;img loading=&#34;lazy&#34; src=&#34;/posts/18163/GitDeployer.png&#34; alt=&#34;GitDeployer&#34; width=&#34;100%&#34; /&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;推送hexo博客到仓库&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#推送hexo博客到仓库&#34;&gt;#&lt;/a&gt; 推送Hexo博客到仓库&lt;/h3&gt;
&lt;p&gt;在三连后追加如下命令, 推送Hexo博客到远程仓库&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;hexo&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; deployer&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#A0ADA0;--shiki-dark:#758575DD&#34;&gt;# 发布三连&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;hexo&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; clean&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &amp;#x26;&amp;#x26;&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt; hexo&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; generate&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &amp;#x26;&amp;#x26;&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt; hexo&lt;/span&gt;&lt;span style=&#34;color:#B56959;--shiki-dark:#C98A7D&#34;&gt; deployer&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;h3 id=&#34;github-pages设置&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#github-pages设置&#34;&gt;#&lt;/a&gt; Github Pages设置&lt;/h3&gt;
&lt;p&gt;选择仓库的 &lt;code&gt;Settings&lt;/code&gt; --&amp;gt; &lt;code&gt;Pages&lt;/code&gt;, 按照下图设置即可, 完成后使用 &lt;code&gt;Github用户名.github.io&lt;/code&gt; 即可访问自己的博客了&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/posts/18163/GithubPages.png&#34; alt=&#34;GitHubPages&#34; width=&#34;100%&#34; /&gt;&lt;/p&gt;
&lt;h2 id=&#34;自定义域名解析&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#自定义域名解析&#34;&gt;#&lt;/a&gt; 自定义域名解析&lt;/h2&gt;
&lt;h3 id=&#34;域名购买&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#域名购买&#34;&gt;#&lt;/a&gt; 域名购买&lt;/h3&gt;
&lt;p&gt;国内推荐 &lt;span class=&#34;blue&#34;&gt;腾讯云&lt;/span&gt; 或者 &lt;span class=&#34;blue&#34;&gt;阿里云&lt;/span&gt; 这样的大厂购买, 如果不想进行备案也可以选择在国外购买(这儿就不做推荐了)&lt;/p&gt;
&lt;div class=&#34;links&#34;&gt;&lt;div class=&#34;item&#34; title=&#34;腾讯云&#34; style=&#34;--block-color:#ff4200;&#34;&gt;&lt;a href=&#34;https://cloud.tencent.com/&#34; class=&#34;image&#34; data-background-image=&#34;https://onlyzyx.com/images/webstack/logo/tencentcloud.png&#34;&gt;&lt;/a&gt;
        &lt;div class=&#34;info&#34;&gt;
        &lt;a href=&#34;https://cloud.tencent.com/&#34; class=&#34;title&#34;&gt;腾讯云&lt;/a&gt;
        &lt;p class=&#34;desc&#34;&gt;腾讯云&lt;/p&gt;
        &lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;item&#34; title=&#34;阿里云&#34; style=&#34;--block-color:#ff4200;&#34;&gt;&lt;a href=&#34;https://www.aliyun.com/&#34; class=&#34;image&#34; data-background-image=&#34;https://onlyzyx.com/images/webstack/logo/aliyun.png&#34;&gt;&lt;/a&gt;
        &lt;div class=&#34;info&#34;&gt;
        &lt;a href=&#34;https://www.aliyun.com/&#34; class=&#34;title&#34;&gt;阿里云&lt;/a&gt;
        &lt;p class=&#34;desc&#34;&gt;阿里云&lt;/p&gt;
        &lt;/div&gt;&lt;/div&gt;&lt;/div&gt;
&lt;h3 id=&#34;域名解析到github-pages&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#域名解析到github-pages&#34;&gt;#&lt;/a&gt; 域名解析到Github Pages&lt;/h3&gt;
&lt;p&gt;&lt;strong&gt;以腾讯云为例&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;假设购买的域名为 &lt;code&gt;onlyzyx.com&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;前往 &lt;code&gt;控制台&lt;/code&gt; --&amp;gt;  &lt;code&gt;DNS 解析 DNSPod&lt;/code&gt; --&amp;gt; &lt;code&gt;我的域名&lt;/code&gt; --&amp;gt; &lt;code&gt;onlyzyx.com&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;这里一般创建两条解析&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/posts/18163/dns.png&#34; alt=&#34;dns&#34; width=&#34;100%&#34; /&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;@&lt;/code&gt; 创建 &lt;code&gt;A&lt;/code&gt; 记录解析 &lt;code&gt;onlyzyx.com&lt;/code&gt; 到 &lt;code&gt;ping 你的用户名.github.io&lt;/code&gt; 显示的&lt;code&gt;ip&lt;/code&gt;地址&lt;/li&gt;
&lt;li&gt;&lt;code&gt;www&lt;/code&gt; 创建 &lt;code&gt;CNAME&lt;/code&gt; 记录解析 &lt;code&gt;onlyzyx.com&lt;/code&gt; 到 &lt;code&gt;你的用户名.github.io&lt;/code&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;然后前往仓库的 &lt;code&gt;Settings&lt;/code&gt; --&amp;gt; &lt;code&gt;Pages&lt;/code&gt;, 按照下图设置即可, 完成后使用 &lt;code&gt;onlyzyx.com&lt;/code&gt; 即可访问自己的博客了(可能稍有延迟, 需要等待 &lt;code&gt;DNS&lt;/code&gt; 解析生效)&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/posts/18163/pagesdns.png&#34; alt=&#34;PagesDNS&#34; width=&#34;100%&#34; /&gt;&lt;/p&gt;

 &lt;h2 id=&#34;引言&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#引言&#34;&gt;#&lt;/a&gt; 引言&lt;/h2&gt;
&lt;p&gt;作为一个社会人, 感觉自己在死瘦宅的路上愈行愈远, 无法自拔~ 也越来越拖延(懒癌晚期)&lt;/p&gt;
&lt;p&gt;为了缓解下这种情况, 决定工作学习之余没事刷刷题, 而 &lt;a href=&#34;https://leetcode.com/&#34;&gt;LeetCode&lt;/a&gt; 就是一个不错的选择(正好也用新入坑的 &lt;code&gt;GO&lt;/code&gt; 语言写写代码试试水)~&lt;/p&gt;
&lt;p&gt;谨以此文记录下 &lt;code&gt;LeetCode&lt;/code&gt; 的刷题之路, 也算是作为一个个人题解 &lt;code&gt;Orz~&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/posts/50504/LeetCode.png&#34; alt=&#34;LeetCode&#34; width=&#34;100%&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;技巧处理&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#技巧处理&#34;&gt;#&lt;/a&gt; 技巧处理&lt;/h3&gt;
&lt;h4 id=&#34;c-输入输出加速&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#c-输入输出加速&#34;&gt;#&lt;/a&gt; C++ 输入输出加速&lt;/h4&gt;
&lt;p&gt;在刷&lt;strong&gt;LeetCode&lt;/strong&gt;的时候, 习惯性看看最优时间的大佬们的解法, 偶然发现有些题同样的方法别人运行时间就要低上不少, 然后发现这些提交一般都有如下这个 &lt;code&gt;Lambda&lt;/code&gt; 表达式。&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-cpp&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#AB5959;--shiki-dark:#CB7676&#34;&gt;static&lt;/span&gt;&lt;span style=&#34;color:#AB5959;--shiki-dark:#CB7676&#34;&gt; const&lt;/span&gt;&lt;span style=&#34;color:#AB5959;--shiki-dark:#CB7676&#34;&gt; auto&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt; __________&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; =&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; &lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;]&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;{&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;    ios&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;::&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;sync_with_stdio&lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;false&lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#B07D48;--shiki-dark:#BD976A&#34;&gt;    cin&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;.&lt;/span&gt;&lt;span style=&#34;color:#59873A;--shiki-dark:#80A665&#34;&gt;tie&lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;nullptr&lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt;    return&lt;/span&gt;&lt;span style=&#34;color:#1E754F;--shiki-dark:#4D9375&#34;&gt; nullptr&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;}&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;(&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;)&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt;;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;仔细看了看 &lt;code&gt;LeetCode&lt;/code&gt; 对于使用 &lt;code&gt;C++&lt;/code&gt; 提交的人, 输入输出默认使用的 &lt;code&gt;C++&lt;/code&gt; 的 &lt;code&gt;io&lt;/code&gt;, 而不是 &lt;code&gt;C&lt;/code&gt; 的, 上面 &lt;code&gt;Lambda&lt;/code&gt; 捕获, 则可以用来解除 &lt;code&gt;C++&lt;/code&gt; 为了兼容 &lt;code&gt;C&lt;/code&gt; 而采取的缓存同步机制, 提升 &lt;code&gt;cin&lt;/code&gt;, &lt;code&gt;cout&lt;/code&gt; 的速度&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;label warning&#34;&gt;&lt;strong&gt;解惑&lt;/strong&gt;&lt;/span&gt; &lt;code&gt;ios::sync_with_stdio(false)&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;因为 &lt;code&gt;C++&lt;/code&gt; 中的&lt;code&gt;std::cin&lt;/code&gt;和&lt;code&gt;std::cout&lt;/code&gt;为了兼容 &lt;code&gt;C&lt;/code&gt;, 保证在代码中同时出现 &lt;code&gt;std::cin&lt;/code&gt; 和 &lt;code&gt;scanf&lt;/code&gt; 或 &lt;code&gt;std::cout&lt;/code&gt; 和 &lt;code&gt;printf&lt;/code&gt; 时输出不发生混乱, 所以 &lt;code&gt;C++&lt;/code&gt; 用一个流缓冲区来同步 &lt;code&gt;C&lt;/code&gt; 的标准流。通过 &lt;code&gt;std::ios_base::sync_with_stdio&lt;/code&gt; 函数可以解除这种同步, 让 &lt;code&gt;std::cin&lt;/code&gt; 和 &lt;code&gt;std::cout&lt;/code&gt; 不再经过缓冲区, 自然就节省了许多时间。&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;label warning&#34;&gt;&lt;strong&gt;解惑&lt;/strong&gt;&lt;/span&gt; &lt;code&gt;cin.tie(nullptr)&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;std::cin &lt;/code&gt;默认是与 &lt;code&gt;std::cout&lt;/code&gt; 绑定的, 所以每次操作的时候(也就是调用 &lt;code&gt;&amp;lt;&amp;lt;&lt;/code&gt; 或者 &lt;code&gt;&amp;gt;&amp;gt;&lt;/code&gt;)都要刷新(调用&lt;code&gt;flush&lt;/code&gt;), 这样增加了IO的负担, 通过 &lt;code&gt;tie(nullptr)&lt;/code&gt; 来解除 &lt;code&gt;std::cin&lt;/code&gt; 和 &lt;code&gt;std::cout&lt;/code&gt; 之间的绑定, 来降低 &lt;code&gt;IO&lt;/code&gt; 的负担使效率提升。&lt;/p&gt;
&lt;h3 id=&#34;题解汇总&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#题解汇总&#34;&gt;#&lt;/a&gt; 题解汇总&lt;/h3&gt;
&lt;p&gt;沉潜深度源自始终如一的专注。人的生命是有限的, 精力是有限的, 只有专注才能将人的力量发挥到极致。&lt;/p&gt;
